using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_200bf11c97424e0b9d5730fd7c001f11;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a logged-in user.
/// </summary>
public class ServerAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _authState = Task.FromResult(
        new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity(
            new[]
            {
                new Claim(ClaimTypes.Name, "bob@example.com"),
                new Claim(ClaimTypes.Email, "bob@example.com"),
                new Claim(ClaimTypes.Role, "User"),
                new Claim(ClaimTypes.Role, "Editor"),
            },
            authenticationType: "Hardcoded"))));

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authState;
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_200bf11c97424e0b9d5730fd7c001f11;

/// <summary>
/// Persists the authentication state into PersistentComponentState so that the
/// WebAssembly client can pick it up after the server-prerendered page activates.
/// </summary>
public class PersistingServerAuthenticationStateProvider : AuthenticationStateProvider, IHostEnvironmentAuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentComponentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authenticationStateTask;

    public PersistingServerAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        _persistentComponentState = persistentComponentState;
        _subscription = _persistentComponentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    /// <summary>
    /// Called by the Blazor infrastructure to supply the current auth state.
    /// </summary>
    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        _authenticationStateTask = authenticationStateTask;
        NotifyAuthenticationStateChanged(_authenticationStateTask);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => _authenticationStateTask ?? Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private async Task OnPersistingAsync()
    {
        var authState = await GetAuthenticationStateAsync();
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var claims = principal.Claims.Select(c => new ClaimData { Type = c.Type, Value = c.Value }).ToArray();
            _persistentComponentState.PersistAsJson(nameof(ClaimData), claims);
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

/// <summary>
/// Serializable DTO for transferring claims from server to client.
/// </summary>
public class ClaimData
{
    public string Type { get; set; } = string.Empty;
    public string Value { get; set; } = string.Empty;
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_200bf11c97424e0b9d5730fd7c001f11.Client;

/// <summary>
/// Client-side AuthenticationStateProvider that reads persisted claims from
/// PersistentComponentState (serialized during server prerendering).
/// </summary>
public class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _unauthenticated =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authenticationStateTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<ClaimData[]>(nameof(ClaimData), out var claimData) && claimData is not null)
        {
            var claims = claimData.Select(c => new Claim(c.Type, c.Value));
            var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
            _authenticationStateTask = Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
        }
        else
        {
            _authenticationStateTask = _unauthenticated;
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => _authenticationStateTask;
}

/// <summary>
/// Serializable DTO matching the server-side ClaimData.
/// </summary>
public class ClaimData
{
    public string Type { get; set; } = string.Empty;
    public string Value { get; set; } = string.Empty;
}

@page "/profile"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto

<PageTitle>Profile</PageTitle>

<h1>Profile</h1>

<AuthorizeView>
    <Authorized>
        <p><strong>Name:</strong> @context.User.Identity?.Name</p>
        <h3>Roles</h3>
        <ul>
            @foreach (var claim in context.User.Claims.Where(c => c.Type == System.Security.Claims.ClaimTypes.Role))
            {
                <li>@claim.Value</li>
            }
        </ul>
    </Authorized>
    <NotAuthorized>
        <p>You are not authenticated.</p>
    </NotAuthorized>
</AuthorizeView>

@page "/editor"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize(Roles = "Editor")]
@rendermode InteractiveAuto

<PageTitle>Editor</PageTitle>

<h1>Editor</h1>

<AuthorizeView Roles="Editor">
    <Authorized>
        <p>Welcome to the editor area, @context.User.Identity?.Name!</p>
    </Authorized>
    <NotAuthorized>
        <p>Access denied. You do not have the Editor role.</p>
    </NotAuthorized>
</AuthorizeView>

@page "/viewer"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto

