using Microsoft.AspNetCore.Components.Authorization;
using sv_200bf11c97424e0b9d5730fd7c001f11;
using sv_200bf11c97424e0b9d5730fd7c001f11.Client.Pages;
using sv_200bf11c97424e0b9d5730fd7c001f11.Components;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents();

builder.Services.AddCascadingAuthenticationState();
builder.Services.AddScoped<AuthenticationStateProvider, ServerAuthenticationStateProvider>();
builder.Services.AddScoped<AuthenticationStateProvider, PersistingServerAuthenticationStateProvider>(sp =>
{
    var persisting = ActivatorUtilities.CreateInstance<PersistingServerAuthenticationStateProvider>(sp);
    var server = sp.GetRequiredService<IEnumerable<AuthenticationStateProvider>>()
        .OfType<ServerAuthenticationStateProvider>().First();
    persisting.SetAuthenticationState(server.GetAuthenticationStateAsync());
    return persisting;
});

var app = builder.Build();

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseWebAssemblyDebugging();
}
else
{
    app.UseExceptionHandler("/Error", createScopeForErrors: true);
}
app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
app.UseAntiforgery();

